/**
 * Event Bus: In-memory publish/subscribe system
 * Enables loose coupling between services
 */

type EventCallback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Publish an event to all subscribers
   */
  publish(event: string, payload: any): void {
    const callbacks = this.subscribers.get(event);
    if (callbacks) {
      callbacks.forEach(callback => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error in subscriber for event "${event}":`, error);
        }
      });
    }
  }

  /**
   * Subscribe to an event
   */
  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }
}

export const eventBus = new EventBus();

/**
 * User Service: Manages users
 * Data: { id, name, email }
 */

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private store: Map<string, User> = new Map();
  private idCounter = 0;

  /**
   * Create a new user
   */
  create(name: string, email: string): User {
    const id = `u${++this.idCounter}`;
    const user: User = { id, name, email };
    this.store.set(id, user);
    return user;
  }

  /**
   * Get a user by ID
   */
  getById(id: string): User | undefined {
    return this.store.get(id);
  }

  /**
   * Get all users
   */
  getAll(): User[] {
    return Array.from(this.store.values());
  }

  /**
   * Update a user
   */
  update(id: string, updates: Partial<Omit<User, 'id'>>): User | undefined {
    const user = this.store.get(id);
    if (!user) return undefined;

    const updated = { ...user, ...updates };
    this.store.set(id, updated);
    return updated;
  }

  /**
   * Delete a user
   */
  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

export const userService = new UserService();

/**
 * Project Service: Manages projects
 * Data: { id, name, description, memberIds[] }
 */

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export class ProjectService {
  private store: Map<string, Project> = new Map();
  private idCounter = 0;

  /**
   * Create a new project
   */
  create(name: string, description: string): Project {
    const id = `p${++this.idCounter}`;
    const project: Project = {
      id,
      name,
      description,
      memberIds: [],
    };
    this.store.set(id, project);
    return project;
  }

  /**
   * Get a project by ID
   */
  getById(id: string): Project | undefined {
    return this.store.get(id);
  }

  /**
   * Get all projects
   */
  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  /**
   * Update a project
   */
  update(
    id: string,
    updates: Partial<Omit<Project, 'id'>>
  ): Project | undefined {
    const project = this.store.get(id);
    if (!project) return undefined;

    const updated = { ...project, ...updates };
    this.store.set(id, updated);
    return updated;
  }

  /**
   * Delete a project
   */
  delete(id: string): boolean {
    return this.store.delete(id);
  }

  /**
   * Add a member to a project
   */
  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;

    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
    }
    return project;
  }

  /**
   * Remove a member from a project
   */
  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.store.get(projectId);
    if (!project) return undefined;

    project.memberIds = project.memberIds.filter(id => id !== userId);
    return project;
  }
}

export const projectService = new ProjectService();

/**
 * Task Service: Manages tasks
 * Data: { id, title, description, status, assigneeId, projectId }
 * Status flow: todo → in-progress → done (forward only)
 * Events published: task.assigned, task.statusChanged
 */

import { eventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export class TaskService {
  private store: Map<string, Task> = new Map();
  private idCounter = 0;

  /**
   * Create a new task
   */
  create(
    title: string,
    description: string,
    projectId: string
  ): Task {
    const id = `t${++this.idCounter}`;
    const task: Task = {
      id,
      title,
      description,
      status: 'todo',
      assigneeId: null,
      projectId,
    };
    this.store.set(id, task);
    return task;
  }

  /**
   * Get a task by ID
   */
  getById(id: string): Task | undefined {
    return this.store.get(id);
  }

  /**
   * Get all tasks
   */
  getAll(): Task[] {
    return Array.from(this.store.values());
  }

  /**
   * Get tasks by project
   */
  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(
      task => task.projectId === projectId
    );
  }

  /**
   * Update a task
   */
  update(
    id: string,
    updates: Partial<Omit<Task, 'id'>>
  ): Task | undefined {
    const task = this.store.get(id);
    if (!task) return undefined;

    const updated = { ...task, ...updates };
    this.store.set(id, updated);
    return updated;
  }

  /**
   * Delete a task
   */
  delete(id: string): boolean {
    return this.store.delete(id);
  }

  /**
   * Assign a task to a user
   */
  assign(taskId: string, assigneeId: string): Task | undefined {
    const task = this.store.get(taskId);
    if (!task) return undefined;

    task.assigneeId = assigneeId;
    this.store.set(taskId, task);

    // Publish event for notification service
    eventBus.publish('task.assigned', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
    });

    return task;
  }

  /**
   * Change task status (forward only: todo → in-progress → done)
   */
  changeStatus(taskId: string, newStatus: TaskStatus): Task | undefined {
    const task = this.store.get(taskId);
    if (!task) return undefined;

    const statusOrder: Record<TaskStatus, number> = {
      'todo': 0,
      'in-progress': 1,
      'done': 2,
    };

    // Only allow forward transitions
    if (statusOrder[newStatus] <= statusOrder[task.status]) {
      throw new Error(
        `Cannot transition from ${task.status} to ${newStatus}. Only forward transitions allowed.`
      );
    }

    const oldStatus = task.status;
    task.status = newStatus;
    this.store.set(taskId, task);

    // Publish event for notification service
    eventBus.publish('task.statusChanged', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    });

    return task;
  }
}

export const taskService = new TaskService();

/**
 * Comment Service: Manages comments on tasks
 * Data: { id, taskId, authorId, body, createdAt }
 * Events published: comment.added
 */

import { eventBus } from '../event-bus';
import { taskService } from './task-service';
import { userService } from './user-service';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: Date;
}

export class CommentService {
  private store: Map<string, Comment> = new Map();
  private idCounter = 0;

  /**
   * Create a new comment
   */
  create(taskId: string, authorId: string, body: string): Comment {
    const id = `c${++this.idCounter}`;
    const comment: Comment = {
      id,
      taskId,
      authorId,
      body,
      createdAt: new Date(),
    };
    this.store.set(id, comment);

    // Publish event for notification service
    const task = taskService.getById(taskId);
    const author = userService.getById(authorId);

    if (task && author) {
      eventBus.publish('comment.added', {
        commentId: comment.id,
        taskId: comment.taskId,
        taskTitle: task.title,
        authorId: comment.authorId,
        authorName: author.name,
      });
    }

    return comment;
  }

  /**
   * Get a comment by ID
   */
  getById(id: string): Comment | undefined {
    return this.store.get(id);
  }

  /**
   * Get comments by task
   */
  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(
      comment => comment.taskId === taskId
    );
  }

  /**
   * Delete a comment
   */
  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

export const commentService = new CommentService();

/**
 * Notification Service: Manages notifications
 * Data: { id, userId, message, read, createdAt }
 * Events subscribed: task.assigned, task.statusChanged, comment.added
 */

import { eventBus } from '../event-bus';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: Date;
}

export class NotificationService {
  private store: Map<string, Notification> = new Map();
  private idCounter = 0;

  constructor() {
    this.setupEventSubscriptions();
  }

  /**
   * Setup subscriptions to events from other services
   */
  private setupEventSubscriptions(): void {
    // Subscribe to task assignment events
    eventBus.subscribe('task.assigned', (payload: any) => {
      if (payload.assigneeId) {
        this.createNotification(
          payload.assigneeId,
          `You have been assigned to task: "${payload.taskTitle}"`
        );
      }
    });

    // Subscribe to task status change events
    eventBus.subscribe('task.statusChanged', (payload: any) => {
      if (payload.assigneeId) {
        this.createNotification(
          payload.assigneeId,
          `Task "${payload.taskTitle}" status changed from ${payload.oldStatus} to ${payload.newStatus}`
        );
      }
    });

    // Subscribe to comment added events
    eventBus.subscribe('comment.added', (payload: any) => {
      // Send notification to task assignee (if any)
      // The router will need to look up the assignee separately
      this.createNotification(
        payload.authorId,
        `You added a comment to task "${payload.taskTitle}"`
      );
    });
  }

  /**
   * Create a notification (internal)
   */
  private createNotification(userId: string, message: string): Notification {
    const id = `n${++this.idCounter}`;
    const notification: Notification = {
      id,
      userId,
      message,
      read: false,
      createdAt: new Date(),
    };
    this.store.set(id, notification);
    return notification;
  }

  /**
   * Get notifications by user
   */
  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter(
      notif => notif.userId === userId
    );
  }

  /**
   * Mark a notification as read
   */
  markAsRead(notificationId: string): Notification | undefined {
    const notification = this.store.get(notificationId);
    if (!notification) return undefined;

    notification.read = true;
    this.store.set(notificationId, notification);
    return notification;
  }

  /**
   * Get all notifications (for testing/demo)
   */
  getAll(): Notification[] {
    return Array.from(this.store.values());
  }
}

export const notificationService = new NotificationService();

/**
 * API Router: HTTP request handler
 * Routes requests to appropriate services
 * Uses Node.js built-in http module only
 */

import { IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import { userService } from './services/user-service';
import { projectService } from './services/project-service';
import { taskService } from './services/task-service';
import { commentService } from './services/comment-service';
import { notificationService } from './services/notification-service';

interface ParsedRequest {
  method: string;
  pathname: string;
  query: Record<string, string>;
  body: any;
}

export async function handleRequest(
  req: IncomingMessage,
  res: ServerResponse
): Promise<void> {
  // Parse URL and body
  const parsedReq = await parseRequest(req);

  // Set response headers
  res.setHeader('Content-Type', 'application/json');

  try {
    const { method, pathname, query, body } = parsedReq;

    // Route to handlers
    if (pathname.startsWith('/users')) {
      return handleUsers(method, pathname, query, body, res);
    } else if (pathname.startsWith('/projects')) {
      return handleProjects(method, pathname, query, body, res);
    } else if (pathname.startsWith('/tasks')) {
      return handleTasks(method, pathname, query, body, res);
    } else if (pathname.startsWith('/comments')) {
      return handleComments(method, pathname, query, body, res);
    } else if (pathname.startsWith('/notifications')) {
      return handleNotifications(method, pathname, query, body, res);
    } else {
      sendResponse(res, 404, { error: 'Not found' });
    }
  } catch (error) {
    console.error('Request error:', error);
    sendResponse(res, 500, {
      error: 'Internal server error',
      message: error instanceof Error ? error.message : String(error),
    });
  }
}

// ============================================================================
// Request parsing
// ============================================================================

async function parseRequest(req: IncomingMessage): Promise<ParsedRequest> {
  const url = new URL(req.url || '', 'http://localhost');
  const method = req.method || 'GET';
  const pathname = url.pathname;
  const query: Record<string, string> = {};

  // Parse query string
  url.searchParams.forEach((value, key) => {
    query[key] = value;
  });

  // Parse body
  let body: any = {};
  if (method !== 'GET' && method !== 'DELETE') {
    body = await readBody(req);
  }

  return { method, pathname, query, body };
}

function readBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', chunk => {
      data += chunk;
    });
    req.on('end', () => {
      try {
        resolve(data ? JSON.parse(data) : {});
      } catch (error) {
        reject(new Error('Invalid JSON body'));
      }
    });
    req.on('error', reject);
  });
}

// ============================================================================
// Response helpers
// ============================================================================

function sendResponse(
  res: ServerResponse,
  statusCode: number,
  data: any
): void {
  res.statusCode = statusCode;
  res.end(JSON.stringify(data));
}

// ============================================================================
// User handlers
// ============================================================================

function handleUsers(
  method: string,
  pathname: string,
  query: Record<string, string>,
  body: any,
  res: ServerResponse
): void {
  const match = pathname.match(/^\/users\/?(.*)$/);
  const id = match?.[1] || '';

  if (method === 'GET' && !id) {
    // GET /users
    const users = userService.getAll();
    return sendResponse(res, 200, users);
  }

  if (method === 'POST' && !id) {
    // POST /users
    const { name, email } = body;
    if (!name || !email) {
      return sendResponse(res, 400, { error: 'Missing name or email' });
    }
    const user = userService.create(name, email);
    return sendResponse(res, 201, user);
  }

  if (method === 'GET' && id) {
    // GET /users/:id
    const user = userService.getById(id);
    if (!user) {
      return sendResponse(res, 404, { error: 'User not found' });
    }
    return sendResponse(res, 200, user);
  }

  if (method === 'PUT' && id) {
    // PUT /users/:id
    const user = userService.update(id, body);
    if (!user) {
      return sendResponse(res, 404, { error: 'User not found' });
    }
    return sendResponse(res, 200, user);
  }

  if (method === 'DELETE' && id) {
    // DELETE /users/:id
    const success = userService.delete(id);
    if (!success) {
      return sendResponse(res, 404, { error: 'User not found' });
    }
    return sendResponse(res, 200, { success: true });
  }

  sendResponse(res, 405, { error: 'Method not allowed' });
}

// ============================================================================
// Project handlers
// ============================================================================

function handleProjects(
  method: string,
  pathname: string,
  query: Record<string, string>,
  body: any,
  res: ServerResponse
): void {
  // Check for member operations
  const memberMatch = pathname.match(/^\/projects\/([^/]+)\/members\/?$/);
  if (memberMatch) {
    const projectId = memberMatch[1];

    if (method === 'POST') {
      // POST /projects/:id/members
      const { userId } = body;
      if (!userId) {
        return sendResponse(res, 400, { error: 'Missing userId' });
      }
      const project = projectService.addMember(projectId, userId);
      if (!project) {
        return sendResponse(res, 404, { error: 'Project not found' });
      }
      return sendResponse(res, 200, project);
    }

    if (method === 'DELETE') {
      // DELETE /projects/:id/members
      const { userId } = body;
      if (!userId) {
        return sendResponse(res, 400, { error: 'Missing userId' });
      }
      const project = projectService.removeMember(projectId, userId);
      if (!project) {
        return sendResponse(res, 404, { error: 'Project not found' });
      }
      return sendResponse(res, 200, project);
    }

    return sendResponse(res, 405, { error: 'Method not allowed' });
  }

  // Regular project operations
  const match = pathname.match(/^\/projects\/?(.*)$/);
  const id = match?.[1] || '';

  if (method === 'GET' && !id) {
    // GET /projects
    const projects = projectService.getAll();
    return sendResponse(res, 200, projects);
  }

  if (method === 'POST' && !id) {
    // POST /projects
    const { name, description } = body;
    if (!name || !description) {
      return sendResponse(res, 400, { error: 'Missing name or description' });
    }
    const project = projectService.create(name, description);
    return sendResponse(res, 201, project);
  }

  if (method === 'GET' && id) {
    // GET /projects/:id
    const project = projectService.getById(id);
    if (!project) {
      return sendResponse(res, 404, { error: 'Project not found' });
    }
    return sendResponse(res, 200, project);
  }

  if (method === 'PUT' && id) {
    // PUT /projects/:id
    const project = projectService.update(id, body);
    if (!project) {
      return sendResponse(res, 404, { error: 'Project not found' });
    }
    return sendResponse(res, 200, project);
  }

  if (method === 'DELETE' && id) {
    // DELETE /projects/:id
    const success = projectService.delete(id);
    if (!success) {
      return sendResponse(res, 404, { error: 'Project not found' });
    }
    return sendResponse(res, 200, { success: true });
  }

  sendResponse(res, 405, { error: 'Method not allowed' });
}

// ============================================================================
// Task handlers
// ============================================================================

function handleTasks(
  method: string,
  pathname: string,
  query: Record<string, string>,
  body: any,
  res: ServerResponse
): void {
  // Check for status change
  const statusMatch = pathname.match(/^\/tasks\/([^/]+)\/status\/?$/);
  if (statusMatch) {
    const taskId = statusMatch[1];
    if (method === 'PUT') {
      const { status } = body;
      if (!status) {
        return sendResponse(res, 400, { error: 'Missing status' });
      }
      try {
        const task = taskService.changeStatus(taskId, status);
        if (!task) {
          return sendResponse(res, 404, { error: 'Task not found' });
        }
        return sendResponse(res, 200, task);
      } catch (error) {
        return sendResponse(res, 400, {
          error: error instanceof Error ? error.message : 'Invalid status',
        });
      }
    }
    return sendResponse(res, 405, { error: 'Method not allowed' });
  }

  // Check for assign
  const assignMatch = pathname.match(/^\/tasks\/([^/]+)\/assign\/?$/);
  if (assignMatch) {
    const taskId = assignMatch[1];
    if (method === 'PUT') {
      const { assigneeId } = body;
      if (!assigneeId) {
        return sendResponse(res, 400, { error: 'Missing assigneeId' });
      }
      const task = taskService.assign(taskId, assigneeId);
      if (!task) {
        return sendResponse(res, 404, { error: 'Task not found' });
      }
      return sendResponse(res, 200, task);
    }
    return sendResponse(res, 405, { error: 'Method not allowed' });
  }

  // Regular task operations
  const match = pathname.match(/^\/tasks\/?(.*)$/);
  const id = match?.[1] || '';

  if (method === 'GET' && !id) {
    // GET /tasks?projectId=X
    const projectId = query.projectId;
    if (projectId) {
      const tasks = taskService.getByProject(projectId);
      return sendResponse(res, 200, tasks);
    }
    const tasks = taskService.getAll();
    return sendResponse(res, 200, tasks);
  }

  if (method === 'POST' && !id) {
    // POST /tasks
    const { title, description, projectId } = body;
    if (!title || !description || !projectId) {
      return sendResponse(res, 400, {
        error: 'Missing title, description, or projectId',
      });
    }
    const task = taskService.create(title, description, projectId);
    return sendResponse(res, 201, task);
  }

  if (method === 'GET' && id) {
    // GET /tasks/:id
    const task = taskService.getById(id);
    if (!task) {
      return sendResponse(res, 404, { error: 'Task not found' });
    }
    return sendResponse(res, 200, task);
  }

  if (method === 'PUT' && id) {
    // PUT /tasks/:id
    const task = taskService.update(id, body);
    if (!task) {
      return sendResponse(res, 404, { error: 'Task not found' });
    }
    return sendResponse(res, 200, task);
  }

  if (method === 'DELETE' && id) {
    // DELETE /tasks/:id
    const success = taskService.delete(id);
    if (!success) {
      return sendResponse(res, 404, { error: 'Task not found' });
    }
    return sendResponse(res, 200, { success: true });
  }

  sendResponse(res, 405, { error: 'Method not allowed' });
}

// ============================================================================
// Comment handlers
// ============================================================================

function handleComments(
  method: string,
  pathname: string,
  query: Record<string, string>,
  body: any,
  res: ServerResponse
): void {
  const match = pathname.match(/^\/comments\/?(.*)$/);
  const id = match?.[1] || '';

  if (method === 'GET' && !id) {
    // GET /comments?taskId=X
    const taskId = query.taskId;
    if (taskId) {
      const comments = commentService.getByTask(taskId);
      return sendResponse(res, 200, comments);
    }
    return sendResponse(res, 400, { error: 'taskId query parameter required' });
  }

  if (method === 'POST' && !id) {
    // POST /comments
    const { taskId, authorId, body: commentBody } = body;
    if (!taskId || !authorId || !commentBody) {
      return sendResponse(res, 400, {
        error: 'Missing taskId, authorId, or body',
      });
    }
    const comment = commentService.create(taskId, authorId, commentBody);
    return sendResponse(res, 201, comment);
  }

  if (method === 'GET' && id) {
    // GET /comments/:id
    const comment = commentService.getById(id);
    if (!comment) {
      return sendResponse(res, 404, { error: 'Comment not found' });
    }
    return sendResponse(res, 200, comment);
  }

  if (method === 'DELETE' && id) {
    // DELETE /comments/:id
    const success = commentService.delete(id);
    if (!success) {
      return sendResponse(res, 404, { error: 'Comment not found' });
    }
    return sendResponse(res, 200, { success: true });
  }

  sendResponse(res, 405, { error: 'Method not allowed' });
}

// ============================================================================
// Notification handlers
// ============================================================================

function handleNotifications(
  method: string,
  pathname: string,
  query: Record<string, string>,
  body: any,
  res: ServerResponse
): void {
  // Check for read operation
  const readMatch = pathname.match(/^\/notifications\/([^/]+)\/read\/?$/);
  if (readMatch) {
    const notifId = readMatch[1];
    if (method === 'PUT') {
      const notif = notificationService.markAsRead(notifId);
      if (!notif) {
        return sendResponse(res, 404, { error: 'Notification not found' });
      }
      return sendResponse(res, 200, notif);
    }
    return sendResponse(res, 405, { error: 'Method not allowed' });
  }

  // Regular notification operations
  const match = pathname.match(/^\/notifications\/?(.*)$/);
  const id = match?.[1] || '';

  if (method === 'GET' && !id) {
    // GET /notifications?userId=X
    const userId = query.userId;
    if (userId) {
      const notifs = notificationService.getByUser(userId);
      return sendResponse(res, 200, notifs);
    }
    return sendResponse(res, 400, { error: 'userId query parameter required' });
  }

  sendResponse(res, 405, { error: 'Method not allowed' });
}

